function normalize(input = {}) { return { ...blankSet(), ...input, categories:Array.isArray(input.categories) ? input.categories : [], cards:Array.isArray(input.cards) ? input.cards.map((card) => typeof card === 'string' ? { text:card } : { id:card?.id, text:String(card?.text || '') }) : [] }; }
function shell(body) { root.innerHTML = `<header class="sponsor-top"><a class="sponsor-brand" href="/admin.html" aria-label="Mingle.Cards 管理画面"><img src="/assets/mingle-cards-masthead.png" alt="Mingle.Cards" /></a><nav><a href="/admin.html">利用状況</a><a href="#" data-logout>ログアウト</a></nav></header>${body}`; root.querySelector('[data-logout]')?.addEventListener('click', logout); root.querySelector('[data-focus]')?.focus(); }
function login(message = '') { root.innerHTML = `<section class="login-view"><a class="sponsor-brand" href="/" aria-label="Mingle.Cards ホーム"><img src="/assets/mingle-cards-masthead.png" alt="Mingle.Cards" /></a><div class="login-card"><p class="eyebrow">ADMIN / SPONSOR CARDS</p><h1>スポンサー提供カード</h1><p class="muted">管理者パスワードでログインしてください。</p><form data-login><label class="field"><span>パスワード</span><input name="password" type="password" autocomplete="current-password" required /></label><p class="status">${esc(message)}</p><button class="button primary" type="submit">ログイン</button></form></div></section>`; root.querySelector('[data-login]').addEventListener('submit', async (event) => { event.preventDefault(); const form = event.currentTarget; const password = form.password.value; if (!password) return; try { await request('/api/admin/session', { method:'POST', body:JSON.stringify({ password }) }); state.authenticated = true; await load(); } catch (error) { form.querySelector('.status').textContent = error.status === 429 ? '試行回数が多すぎます。しばらく待ってください。' : 'ログインできませんでした。'; } }); }
async function logout(event) { event.preventDefault(); if (state.busy) return; await request('/api/admin/session', { method:'DELETE' }).catch(() => {}); state.authenticated = false; login(); }
async function stopSet(id) { if (state.busy) return; const set = state.sets.find((item) => String(item.id) === String(id)); if (!set) return; state.busy = true; state.error = ''; listView(); try { await request(`/api/admin/sponsors?id=${encodeURIComponent(id)}`, { method:'PATCH', body:JSON.stringify({ ...set, status:'draft' }) }); await load(); } catch { state.busy = false; state.error = '公開停止できませんでした。'; listView(); } }
function listView() { const rows = state.sets.length ? state.sets.map((set) => `<article class="set-row"><div><h3>${esc(set.title || '名称未設定')}</h3><p>${esc(set.providerName || '提供元未設定')} · ${set.cards?.length || 0}枚</p></div><div class="set-actions"><span class="set-status">${esc(statusLabel(set.status))}</span><button class="button subtle" data-edit="${esc(set.id)}" ${state.busy ? 'disabled' : ''}>編集</button>${set.status === 'published' ? `<button class="button subtle" data-stop="${esc(set.id)}" ${state.busy ? 'disabled' : ''}>公開停止</button>` : ''}</div></article>`).join('') : '<p class="empty">スポンサー提供カードはまだありません。</p>'; shell(`<main class="sponsor-main"><div class="sponsor-heading"><div><p class="eyebrow">ADMIN / SPONSOR CARDS</p><h1 data-focus>スポンサー提供カード</h1><p class="muted">公式提供者名とスポンサー表示を添えて、会話の時間をつくるカードを管理します。</p></div><div class="top-actions"><button class="button primary" data-new ${state.busy ? 'disabled' : ''}>新しく作る</button></div></div><p class="status">${esc(state.error)}</p><section class="panel"><h2>登録済みのカード</h2><div class="set-list">${rows}</div></section></main>`); root.querySelector('[data-new]')?.addEventListener('click', () => { state.editing = blankSet(); state.dirty = false; editor(); }); root.querySelectorAll('[data-edit]').forEach((button) => button.addEventListener('click', () => { state.editing = normalize(state.sets.find((set) => String(set.id) === button.dataset.edit)); state.dirty = false; editor(); })); root.querySelectorAll('[data-stop]').forEach((button) => button.addEventListener('click', () => stopSet(button.dataset.stop))); }
function preview(set) { const card = set.cards.find((item) => item.text.trim())?.text || 'ここにカードの内容が表示されます'; const href = safeSiteUrl(set.siteUrl); const design = cardDesignForSession({ sponsorSet:true, sponsor:{ ...set } }); const front = set.cardFrontUrl || design.front; const back = set.cardBackUrl || design.back; const faceStyle = (url) => 'background-image:url(&quot;' + esc(url) + '&quot;)'; return `<aside class="panel"><h2>表示プレビュー</h2><p class="section-note">実際の表示に近い形で、スポンサー表示と終了後の案内を確認できます。</p><article class="preview-card"><section class="preview-catalog"><span class="sponsor-mark">スポンサー</span><h3>${esc(set.title || 'セット名')}</h3><p class="preview-provider">${esc(set.providerName || '提供元名')}の公式カード</p>${set.thumbnailUrl ? `<img class="preview-cover-image" src="${esc(set.thumbnailUrl)}" alt="一覧サムネイルのプレビュー">` : ''}<p>${esc(set.description || 'セットの説明がここに表示されます。')}</p><div class="preview-question"><div class="preview-tabs"><button type="button" class="text-button is-active" data-preview-side="front">表</button><button type="button" class="text-button" data-preview-side="back">裏</button></div><div class="preview-card-face" data-preview-face style="${faceStyle(front)}"><strong>${esc(card)}</strong></div></div></section></article><section class="preview-end-section"><h3>終了後の表示</h3><section class="preview-end"><strong>${esc(set.endMessage || '終了後メッセージがここに表示されます。')}</strong>${href ? `<a href="${esc(href)}" rel="noopener noreferrer">${esc(set.ctaLabel || 'スポンサーサイトを見る')}</a>` : ''}</section></section></aside>`; }
function editor() { const set = state.editing; const allowed = allowedCategories(set.audience); const designOptions = CREATOR_PRESET_IDS.map((id) => `<label><input type="radio" name="design" value="${id}" ${set.design?.presetId === id ? 'checked' : ''} ${state.busy ? 'disabled' : ''}>${esc(CREATOR_PRESETS[id].label)}</label>`).join(''); const categoryRows = categoryInfo.filter(([id]) => allowed.includes(id)).map(([id, label]) => `<label><input type="checkbox" name="category" value="${esc(id)}" ${set.categories.includes(id) ? 'checked' : ''} ${state.busy ? 'disabled' : ''}>${esc(label)}</label>`).join(''); const cards = set.cards.map((card, index) => `<div class="card-row"><span class="card-number">${index + 1}</span><textarea name="card" maxlength="300" required aria-label="${index + 1}枚目のカード" ${state.busy ? 'disabled' : ''}>${esc(card.text)}</textarea>${set.cards.length > 6 ? `<button type="button" class="remove-card" data-remove="${index}" ${state.busy ? 'disabled' : ''}>外す</button>` : '<span></span>'}</div>`).join(''); const published = set.status === 'published'; shell(`<main class="sponsor-main"><div class="sponsor-heading"><div><p class="eyebrow">ADMIN / SPONSOR CARDS</p><h1 data-focus>${set.id ? 'スポンサー提供カードを編集' : 'スポンサー提供カードを作る'}</h1><p class="muted">スポンサーであることを明示し、終了後に次の案内を表示できます。</p></div></div><p class="status">${esc(state.error)}</p><div class="editor-layout"><form class="panel" data-editor><h2>カードの設定</h2><p class="section-note">6〜40枚のカードを登録できます。公開前に表示プレビューで内容を確認してください。</p><div class="form-grid"><label class="field"><span>公式提供者名</span><input name="providerName" maxlength="80" value="${esc(set.providerName)}" placeholder="例：Mingle.Cards編集部" required ${state.busy ? 'disabled' : ''}><small>表示例：「Mingle.Cards編集部の公式カード」</small></label><label class="field"><span>セット名</span><input name="title" maxlength="120" value="${esc(set.title)}" placeholder="例：仕事の合間のひとこと" required ${state.busy ? 'disabled' : ''}></label><label class="field wide"><span>セットの内容</span><textarea name="description" maxlength="500" placeholder="どんな時間に使うカードかを書きます。" ${state.busy ? 'disabled' : ''}>${esc(set.description)}</textarea></label><fieldset class="field wide design-options"><legend>カードのデザイン</legend><div class="design-list"><label><input type="radio" name="design" value="" ${!set.design ? 'checked' : ''} ${state.busy ? 'disabled' : ''}>標準</label>${designOptions}</div><p class="section-note">画像を指定しない面は、選択したプリセットのデザインを使います。</p><div class="image-fields"><label class="field"><span>一覧サムネイル</span><small>PNG・JPEG・WebP、3MiB以下・4096px以下</small><input type="file" accept="image/png,image/jpeg,image/webp" data-cover-image ${state.busy ? 'disabled' : ''}>${set.thumbnailPath ? `<button type="button" class="text-button" data-clear-image="thumbnailPath" ${state.busy ? 'disabled' : ''}>外す</button>` : ''}</label><label class="field"><span>カード表</span><small>PNG・JPEG・WebP、3MiB以下・4096px以下</small><input type="file" accept="image/png,image/jpeg,image/webp" data-card-front-image ${state.busy ? 'disabled' : ''}>${set.cardFrontPath ? `<button type="button" class="text-button" data-clear-image="cardFrontPath" ${state.busy ? 'disabled' : ''}>外す</button>` : ''}</label><label class="field"><span>カード裏</span><small>PNG・JPEG・WebP、3MiB以下・4096px以下</small><input type="file" accept="image/png,image/jpeg,image/webp" data-card-back-image ${state.busy ? 'disabled' : ''}>${set.cardBackPath ? `<button type="button" class="text-button" data-clear-image="cardBackPath" ${state.busy ? 'disabled' : ''}>外す</button>` : ''}</label></div></fieldset><fieldset class="field wide"><legend>対象カテゴリ</legend><div class="category-list">${categoryRows}</div></fieldset><fieldset class="field wide"><legend>対象</legend><div class="audience-list"><label><input type="radio" name="audience" value="group" ${set.audience === 'group' ? 'checked' : ''} ${state.busy ? 'disabled' : ''}>みんなで</label><label><input type="radio" name="audience" value="solo" ${set.audience === 'solo' ? 'checked' : ''} ${state.busy ? 'disabled' : ''}>ひとりで</label><label><input type="radio" name="audience" value="both" ${set.audience === 'both' ? 'checked' : ''} ${state.busy ? 'disabled' : ''}>どちらでも</label></div></fieldset><label class="check-field"><input type="checkbox" name="isR18" ${set.isR18 || set.categories.includes('adult') ? 'checked' : ''} ${set.categories.includes('adult') || state.busy ? 'disabled' : ''}>成人向け（R18）</label></div><h2>カード</h2><p class="section-note">CSV/Excel（.xlsx）の取込は内容を確認してから反映します。既存カードは上書きしません。</p><input type="file" accept=".csv,.xlsx" data-import-file hidden><button type="button" class="button subtle" data-import ${state.busy ? 'disabled' : ''}>質問を一括取込</button><label class="import-header"><input type="checkbox" data-import-header ${state.busy ? 'disabled' : ''} ${state.importHeaderOverride === null ? 'checked' : (state.importHeaderOverride ? 'checked' : '')}>先頭行を見出しとして扱う</label><div class="import-preview" data-import-preview hidden></div><div class="card-list">${cards}</div><p class="count-note" data-count>${set.cards.length} / 40枚</p><button type="button" class="button subtle" data-add ${set.cards.length >= 40 || state.busy ? 'disabled' : ''}>カードを追加</button><h2>終了後の案内</h2><p class="section-note">最後のカードのあとに表示するメッセージと、スポンサーサイトへのリンクを設定します。</p><label class="field"><span>終了後メッセージ</span><textarea name="endMessage" maxlength="500" placeholder="例：この時間を応援してくれた〇〇からのお知らせです。" ${state.busy ? 'disabled' : ''}>${esc(set.endMessage)}</textarea></label><div class="form-grid"><label class="field"><span>スポンサーサイトURL（HTTPS）</span><input name="siteUrl" type="url" inputmode="url" placeholder="https://example.com" value="${esc(set.siteUrl)}" ${state.busy ? 'disabled' : ''}></label><label class="field"><span>リンク名</span><input name="ctaLabel" maxlength="40" value="${esc(set.ctaLabel)}" placeholder="スポンサーサイトを見る" ${state.busy ? 'disabled' : ''}></label></div><div class="form-actions"><button class="button primary" name="save" value="${published ? 'published' : 'draft'}" type="submit" ${state.busy ? 'disabled' : ''}>${published ? '公開内容を保存' : '下書き保存'}</button>${published ? '' : `<button class="button primary" name="save" value="published" type="submit" ${state.busy ? 'disabled' : ''}>公開する</button>`}<button class="button subtle" type="button" data-cancel ${state.busy ? 'disabled' : ''}>一覧へ戻る</button></div></form>${preview(set)}</div></main>`); bindEditor(); }
function readForm(form, statusOverride) { const data = new FormData(form); const audience = data.get('audience') || 'group'; const categories = data.getAll('category').filter((id) => allowedCategories(audience).includes(id)); return normalize({ ...state.editing, providerName:String(data.get('providerName') || '').trim(), title:String(data.get('title') || '').trim(), description:String(data.get('description') || '').trim(), categories, audience, cards:data.getAll('card').map((text, index) => ({ ...(state.editing.cards[index]?.id ? { id:state.editing.cards[index].id } : {}), text:String(text).trim() })), endMessage:String(data.get('endMessage') || '').trim(), siteUrl:String(data.get('siteUrl') || '').trim(), ctaLabel:String(data.get('ctaLabel') || '').trim(), design:(form.querySelector('input[name=design][value=""]:checked') ? null : (data.get('design') ? {version:1,kind:'preset',presetId:String(data.get('design'))} : (state.editing.id ? null : {version:1,kind:'preset',presetId:'friends'}))), thumbnailPath:state.editing.thumbnailPath || '', cardFrontPath:state.editing.cardFrontPath || '', cardBackPath:state.editing.cardBackPath || '', isR18:data.get('isR18') === 'on' || categories.includes('adult'), status:statusOverride || state.editing.status }); }
function validate(set) { if (!set.providerName || !set.title || !set.description) return '提供者名、セット名、セットの内容を入力してください。'; if (Array.from(set.providerName).length > 80 || Array.from(set.title).length > 120 || Array.from(set.description).length > 500 || Array.from(set.endMessage).length > 500 || Array.from(set.ctaLabel).length > 40) return '入力できる文字数を超えています。'; if (!set.categories.length) return '対象カテゴリを1つ以上選んでください。'; if (!['group','solo','both'].includes(set.audience)) return '対象を選んでください。'; if (set.cards.length < 6 || set.cards.length > 40 || set.cards.some((card) => !card.text || Array.from(card.text).length > 300)) return 'カードは6〜40枚で、1枚300文字以内で入力してください。'; if (set.siteUrl && !safeSiteUrl(set.siteUrl)) return 'スポンサーサイトURLはHTTPSで入力してください。'; if (set.siteUrl && !set.ctaLabel) return 'サイトへのリンク名を入力してください。'; return ''; }
function bindPreview() {
  root.querySelectorAll('[data-preview-side]').forEach((button) => button.addEventListener('click', () => {
    const face = root.querySelector('[data-preview-face]');
    const design = cardDesignForSession({ sponsorSet:true, sponsor:{ ...state.editing } });
    const url = button.dataset.previewSide === 'back' ? (state.editing.cardBackUrl || design.back) : (state.editing.cardFrontUrl || design.front);
    if (face) { face.style.backgroundImage = 'url("' + esc(url) + '")'; face.classList.toggle('is-back', button.dataset.previewSide === 'back'); }
    root.querySelectorAll('[data-preview-side]').forEach((item) => item.classList.toggle('is-active', item === button));
  }));
}
function bindEditor() {
  const form = root.querySelector('[data-editor]');
  const markDirty = () => { state.dirty = true; };
  const refreshPreview = () => { const target = root.querySelector('.editor-layout > .panel:last-child'); if (target) { target.outerHTML = preview(state.editing); bindPreview(); } };
  bindPreview();
  form.querySelectorAll('input,textarea,select').forEach((input) => input.addEventListener('input', () => { if (state.busy) return; markDirty(); state.editing = readForm(form); const count = root.querySelector('[data-count]'); if (count) count.textContent = String(state.editing.cards.length) + ' / 40枚'; refreshPreview(); }));
  form.querySelectorAll('input[name="audience"]').forEach((input) => input.addEventListener('change', () => { state.editing = readForm(form); state.editing.categories = state.editing.categories.filter((id) => allowedCategories(state.editing.audience).includes(id)); editor(); state.dirty = true; }));
  root.querySelector('[data-import]')?.addEventListener('click', () => root.querySelector('[data-import-file]')?.click());
  root.querySelector('[data-import-header]')?.addEventListener('change', () => { state.importHeaderOverride = root.querySelector('[data-import-header]').checked; const input = root.querySelector('[data-import-file]'); if (input?.files?.length) input.dispatchEvent(new Event('change', { bubbles:true })); });
  root.querySelector('[data-import-file]')?.addEventListener('change', async (event) => {
    const file = event.target.files?.[0]; if (!file) return;
    try {
      const headerToggle = root.querySelector('[data-import-header]');
      const parsed = await parseSponsorImport(file, { hasHeader: state.importHeaderOverride });
      if (state.importHeaderOverride === null && headerToggle) headerToggle.checked = parsed.hasHeader;
      const renderImport = (selected) => {
        const column = Number.isInteger(selected) ? selected : parsed.questionColumn;
        const result = column === null || column === undefined ? parsed : selectQuestionColumn(parsed, column);
        const rows = result.questions || []; const errors = result.errors || []; const existingCount = readForm(form).cards.filter((card) => card.text).length; const overLimit = existingCount + rows.length > 40; const valid = errors.length === 0 && !overLimit;
        const candidates = result.candidates || parsed.candidates || [];
        const options = (column === null || column === undefined ? '<option value="" selected>質問列を選択</option>' : '') + candidates.map((candidate) => '<option value="' + candidate.index + '" ' + (candidate.index === (result.questionColumn ?? column) ? 'selected' : '') + '>' + esc(candidate.header || ('列' + (candidate.index + 1))) + '</option>').join('');
        const errorText = [...errors.map((item) => item.code === 'QUESTION_TOO_LONG' ? ('300文字を超える質問があります（行' + item.row + '）。') : item.code === 'QUESTION_COUNT' ? '質問は6〜40件で指定してください。' : item.code === 'QUESTION_COLUMN_REQUIRED' ? '質問列を選択してください。' : '').filter(Boolean), ...(overLimit ? ['既存カードと合わせて40枚を超えるため反映できません。'] : [])].filter((value,index,array)=>array.indexOf(value)===index).join(' ');
        const importPreview = root.querySelector('[data-import-preview]'); if (!importPreview) return;
        importPreview.hidden = false;
        importPreview.innerHTML = '<label>質問列<select data-import-column>' + options + '</select></label><p data-import-count>' + rows.length + '件を確認できます。' + (errorText ? ' ' + esc(errorText) : '') + '</p><ol data-import-rows>' + rows.slice(0, 40).map((row) => '<li>' + esc(row.text) + '</li>').join('') + '</ol><button type="button" class="button subtle" data-import-apply ' + (valid ? '' : 'disabled') + '>この内容を反映</button>';
        const select = importPreview.querySelector('[data-import-column]'); select?.addEventListener('change', () => renderImport(select.value === '' ? null : Number(select.value)));
        importPreview.querySelector('[data-import-apply]')?.addEventListener('click', () => { const current = readForm(root.querySelector('[data-editor]')); const existing = current.cards.filter((card) => card.text); if (existing.length + rows.length > 40 || !valid) return; state.editing = current; state.editing.cards = [...existing, ...rows]; state.dirty = true; editor(); });
      };
      renderImport(parsed.questionColumn);
    } catch (error) { state.error = error?.code === 'QUESTION_COLUMN_REQUIRED' ? '質問列を選択してください。' : error?.code === 'QUESTION_TOO_LONG' ? '300文字を超える質問があります。' : 'ファイルを読み込めませんでした。'; editor(); }
  });
  async function uploadSponsorImage(file, kind, pathKey, urlKey) {
    if (state.busy) return;
    if (!['image/png','image/jpeg','image/webp'].includes(file.type) || file.size > 3 * 1024 * 1024) { state.error = '画像はPNG・JPEG・WebP、3MiB以下で指定してください。'; editor(); return; }
    state.busy = true; state.error = ''; editor();
    try { const reader = new FileReader(); const data = await new Promise((resolve, reject) => { reader.onload = () => resolve(reader.result); reader.onerror = reject; reader.readAsDataURL(file); }); const payload = await request('/api/admin/sponsors?asset=1', { method:'POST', body:JSON.stringify({ kind, imageData:data }) }); state.editing[pathKey] = payload.asset?.path || ''; state.editing[urlKey] = payload.asset?.url || ''; state.dirty = true; }
    catch (error) { state.error = error?.status === 413 ? '画像の容量が大きすぎます。3MiB以下の画像を選んでください。' : '画像をアップロードできませんでした。既存の画像はそのままです。'; }
    finally { state.busy = false; editor(); }
  }
  root.querySelector('[data-cover-image]')?.addEventListener('change', async (event) => { const file = event.target.files?.[0]; if (file) await uploadSponsorImage(file, 'thumbnail', 'thumbnailPath', 'thumbnailUrl'); });
  root.querySelector('[data-card-front-image]')?.addEventListener('change', async (event) => { const file = event.target.files?.[0]; if (file) await uploadSponsorImage(file, 'cardFront', 'cardFrontPath', 'cardFrontUrl'); });
  root.querySelector('[data-card-back-image]')?.addEventListener('change', async (event) => { const file = event.target.files?.[0]; if (file) await uploadSponsorImage(file, 'cardBack', 'cardBackPath', 'cardBackUrl'); });
  root.querySelectorAll('[data-clear-image]').forEach((button) => button.addEventListener('click', () => { state.editing[button.dataset.clearImage] = ''; state.editing[button.dataset.clearImage.replace('Path','Url')] = ''; state.dirty = true; editor(); }));
  root.querySelector('[data-add]')?.addEventListener('click', () => { if (state.editing.cards.length >= 40 || state.busy) return; state.editing = readForm(form); state.editing.cards.push({ text:'' }); editor(); state.dirty = true; requestAnimationFrame(() => root.querySelectorAll('textarea[name="card"]')[state.editing.cards.length - 1]?.focus()); });
  root.querySelectorAll('[data-remove]').forEach((button) => button.addEventListener('click', () => { state.editing = readForm(form); state.editing.cards.splice(Number(button.dataset.remove), 1); editor(); state.dirty = true; }));
  root.querySelector('[data-cancel]')?.addEventListener('click', () => { if (state.dirty && !window.confirm('入力中の内容を破棄して一覧へ戻りますか？')) return; state.dirty = false; listView(); });
  form.addEventListener('submit', async (event) => { event.preventDefault(); if (state.busy) return; const set = readForm(form, event.submitter?.value || 'draft'); const error = validate(set); if (error) { state.error = error; editor(); return; } state.busy = true; state.error = ''; editor(); try { const path = state.editing.id ? '/api/admin/sponsors?id=' + encodeURIComponent(state.editing.id) : '/api/admin/sponsors'; const payload = await request(path, { method:state.editing.id ? 'PATCH' : 'POST', body:JSON.stringify(set) }); state.editing = normalize(payload.set || set); state.dirty = false; await load(); } catch (requestError) { state.error = requestError.status === 401 ? 'セッションの有効期限が切れました。' : '保存できませんでした。入力内容を確認してください。'; state.busy = false; editor(); } });
}
async function load() { state.busy = true; try { const payload = await request('/api/admin/sponsors'); state.sets = Array.isArray(payload?.sets) ? payload.sets.map(normalize) : []; state.authenticated = true; state.busy = false; listView(); } catch (error) { state.busy = false; if (error.status === 401) { state.authenticated = false; login(''); } else { state.error = 'スポンサー提供カードを読み込めませんでした。'; listView(); } } }
window.addEventListener('beforeunload', (event) => { if (state.dirty) { event.preventDefault(); event.returnValue = ''; } });
async function init() { try { await request('/api/admin/session'); await load(); } catch (error) { login(error.status === 503 ? '管理画面は現在利用できません。' : ''); } }
init();
